{
  "paper_id": "P004079",
  "problem": [
    {
      "concept": "NMT cannot handle a larger vocabulary because training complexity and decoding complexity proportionally increase with the number of target words",
      "evidence_id": "A1"
    },
    {
      "concept": "This problem becomes even more serious when translating patent documents, which contain many technical terms that are observed infrequently",
      "evidence_id": "A2"
    }
  ],
  "task": [
    {
      "concept": "translate patent sentences comprising a large vocabulary of technical terms",
      "evidence_id": "A4"
    }
  ],
  "method": [
    {
      "concept": "train an NMT system on bilingual data wherein technical terms are replaced with technical term tokens",
      "evidence_id": "A5"
    },
    {
      "concept": "use it as a decoder to translate source sentences with technical term tokens and replace the tokens with technical term translations using SMT",
      "evidence_id": "A6"
    },
    {
      "concept": "rerank the 1,000-best SMT translations on the basis of the average of the SMT score and that of the NMT rescoring of the translated sentences with technical term tokens",
      "evidence_id": "A7"
    }
  ],
  "dataset": [
    {
      "concept": "Japanese-Chinese patent sentences",
      "evidence_id": "A8"
    }
  ],
  "contribution": [
    {
      "concept": "proposed NMT system achieves a substantial improvement of up to 3.1 BLEU points and 2.3 RIBES points over traditional SMT systems and an improvement of approximately 0.6 BLEU points and 0.8 RIBES points over an equivalent NMT system without our proposed technique",
      "evidence_id": "A8"
    }
  ]
}

